krpano.cssstyles:
:root {
	--overview-hotspot-primary: #387873;
	--overview-tag-offset-x: -5px;
}

.overview-hotspot-tag {
	position: relative;
	z-index: 0;
	isolation: isolate;
	display: inline-block;
	overflow: visible;
	color: #FFFFFF;
	font-family: "Montserrat", sans-serif;
	font-size: 14px;
	font-weight: 600;
	line-height: 20px;
	white-space: nowrap;
	box-sizing: border-box;
	pointer-events: none;
}

.overview-hotspot-title {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: 8px 30px;
	border: 1px solid transparent;
	border-radius: 999px;
	background:
		linear-gradient(var(--overview-hotspot-primary), var(--overview-hotspot-primary)) padding-box,
		linear-gradient(90deg, rgba(105,188,177,1) 0%, rgba(122,234,229,1) 51%, rgba(105,188,177,0.8) 100%) border-box;
	box-sizing: border-box;
	transform: translateX(var(--overview-tag-offset-x));
}

.overview-hotspot-subtitle {
	position: absolute;
	left: calc(30px + var(--overview-tag-offset-x));
	top: calc(100% + 8px);
	display: inline-flex;
	align-items: center;
	gap: 5px;
	color: #FFFFFF;
	font-family: "Montserrat", sans-serif;
	font-size: 11px;
	font-weight: 500;
	line-height: 14px;
	white-space: nowrap;
	pointer-events: none;
	text-shadow: 0 1px 4px rgba(0,0,0,0.35);
}

.overview-hotspot-subtitle::before {
	content: "";
	display: block;
	width: 18px;
	height: 18px;
	flex: 0 0 18px;
	background-image: url("./assets/images/icon-car-wheel.svg?v=2");
	background-position: center;
	background-repeat: no-repeat;
	background-size: contain;
}

.overview-hotspot-dot {
	display: block;
	z-index: 3;
	width: 12px;
	height: 12px;
	border: 1px solid #FFFFFF;
	border-radius: 50%;
	background: radial-gradient(circle, #1F4F4B 0 3px, #387873 3px 6px, rgba(216,255,255,0.9) 100%);
	box-shadow:
		0 0 4px 2px rgba(216,255,255,0.42),
		0 0 10px 5px rgba(122,234,229,0.28),
		0 0 18px 9px rgba(56,120,115,0.18),
		0 0 30px 15px rgba(216,255,255,0.10);
	box-sizing: border-box;
	animation: overview-hotspot-dot-pulse 1.45s ease-in-out infinite;
}

@keyframes overview-hotspot-dot-pulse {
	0%, 100% {
		box-shadow:
			0 0 4px 2px rgba(216,255,255,0.34),
			0 0 10px 5px rgba(122,234,229,0.22),
			0 0 18px 9px rgba(56,120,115,0.14),
			0 0 30px 15px rgba(216,255,255,0.08);
		filter: brightness(1);
	}

	50% {
		box-shadow:
			0 0 6px 3px rgba(216,255,255,0.62),
			0 0 16px 8px rgba(122,234,229,0.38),
			0 0 28px 14px rgba(56,120,115,0.24),
			0 0 44px 22px rgba(216,255,255,0.14);
		filter: brightness(1.28);
	}
}

krpano.action:
var lineHeight = caller["data-line-height"] || "80";
lineHeight = String(lineHeight).replace("px", "").trim();
var lineHeightNumber = parseFloat(lineHeight) || 80;
var title = caller.html || "";
var subtitle = caller["data-subtitle"] || "";
var subtitleHeight = subtitle ? (caller["data-subtitle-height"] || "22") : "0";
subtitleHeight = String(subtitleHeight).replace("px", "").trim();
var subtitleHeightNumber = parseFloat(subtitleHeight) || 0;
var tagHalfHeight = caller["data-tag-half-height"] || "19";
tagHalfHeight = String(tagHalfHeight).replace("px", "").trim();
var tagHalfHeightNumber = parseFloat(tagHalfHeight) || 19;
caller.oy = -(lineHeightNumber - subtitleHeightNumber) + tagHalfHeightNumber;
caller.html = '<span class="overview-hotspot-title">' + title + '</span>' +
	(subtitle ? '<span class="overview-hotspot-subtitle">' + subtitle + '</span>' : '');

var hotspotElement = caller.sprite || caller.htmlsprite || caller.element;
var tagElement = hotspotElement && hotspotElement.querySelector
	? (hotspotElement.querySelector(".overview-hotspot-tag") || hotspotElement)
	: hotspotElement;

if (tagElement && tagElement.style) {
	tagElement.style.setProperty("--overview-line-height", lineHeight + "px");
	tagElement.setAttribute("data-line-height", lineHeight);
}

var lineName = caller.name + "_line";
if (!krpano.get("hotspot[" + lineName + "]")) {
	krpano.call("addhotspot(" + lineName + ");");
}

krpano.set("hotspot[" + lineName + "].ath", caller.ath);
krpano.set("hotspot[" + lineName + "].atv", caller.atv);
krpano.set("hotspot[" + lineName + "].height", lineHeightNumber);
krpano.call("hotspot[" + lineName + "].loadstyle(overview_hotspot_line);");
krpano.set("hotspot[" + lineName + "].height", lineHeightNumber);
krpano.set("hotspot[" + lineName + "].visible", true);

var dotName = caller.name + "_dot";
if (!krpano.get("hotspot[" + dotName + "]")) {
	krpano.call("addhotspot(" + dotName + ");");
}

krpano.set("hotspot[" + dotName + "].ath", caller.ath);
krpano.set("hotspot[" + dotName + "].atv", caller.atv);
krpano.call("hotspot[" + dotName + "].loadstyle(overview_hotspot_dot);");
krpano.set("hotspot[" + dotName + "].visible", true);

var eventDetail = {
	name: caller.name,
	ath: caller.ath,
	atv: caller.atv
};
var event;

if (typeof window.CustomEvent === "function") {
	event = new CustomEvent("overview:hotspot-click", {
		detail: eventDetail
	});
} else {
	event = document.createEvent("CustomEvent");
	event.initCustomEvent("overview:hotspot-click", true, true, eventDetail);
}

window.dispatchEvent(event);
